    apLoadGameBuffer->LoadData(&bSwimming, 1u);
    apLoadGameBuffer->LoadData(&iActionValue, 4u);
    apLoadGameBuffer->LoadData(&fTimeronAction, 4u);
    apLoadGameBuffer->LoadData(&fHeadTrackTimer, 4u);
