                this->DoDamage(fdamage, 0.0f, nullptr);
                float v47 = this->GetHeight() * 0.5;
                NiPoint3* a3_4 = ::new (&v46) NiPoint3(NiPoint3_UNIT_Z * v47);
                NiNode* v18 = this->Get3D();
                NiPoint3 targetPos = v18->GetWorldTranslate() + *a3_4;
