int32_t
Actor::GetFactionReaction(Actor* apActor, int32_t& airank, TESFaction*& apthisfaction, TESFaction*& aptargfaction) {
    uint32_t v5;
    BSSimpleList<FACTION_RANK*>* apList2;
    TESFaction* apFactionArray[129];
    TESFaction* phisFactionArray[128];
    int32_t ihighestReaction = -100000;
    int32_t ilowestReaction = 100000;
    int32_t ireturnReaction = 0;
    BSSimpleList<FACTION_RANK*>* pmyFactionList = &GetActorBase()->listFactions;
    BSSimpleList<FACTION_RANK*>* phisFactionList = &apActor->GetActorBase()->listFactions;
    ExtraFactionChanges* pmyFactionChanges = (&m_Extra)->GetFactionChangesExtra();
    ExtraFactionChanges* phisFactionChanges = (&apActor->m_Extra)->GetFactionChangesExtra();
    if (pmyFactionChanges) {
        apList2 = pmyFactionChanges->pFactionChanges;
    }
    else {
        apList2 = nullptr;
    }
    uint32_t imyCount = IntegrateFactionLists(apFactionArray, 128u, pmyFactionList, apList2);
    if (phisFactionChanges) {
        v5 = IntegrateFactionLists(phisFactionArray, 128u, phisFactionList, phisFactionChanges->pFactionChanges);
    }
    else {
        v5 = IntegrateFactionLists(phisFactionArray, 128u, phisFactionList, nullptr);
    }
    for (uint32_t i = 0; i < imyCount; ++i) {
        if (apFactionArray[i]) {
            for (uint32_t j = 0; j < v5; ++j) {
                if (phisFactionArray[j]) {
                    if (apFactionArray[i] == phisFactionArray[j]) {
                        int32_t ireaction = apFactionArray[i]->GetReaction(apFactionArray[i]);
                        if (ireaction > ihighestReaction) {
                            ihighestReaction = ireaction;
                            airank = 1;
                            apthisfaction = apFactionArray[i];
                            aptargfaction = apFactionArray[i];
                            ireturnReaction = ireaction;
                        }
                    }
                    else {
                        if (ihighestReaction == -100000) {
                            int32_t ireaction_2 = apFactionArray[i]->GetReaction(phisFactionArray[j]);
                            if (ireaction_2 < ilowestReaction) {
                                ilowestReaction = ireaction_2;
                                airank = 1;
                                apthisfaction = apFactionArray[i];
                                aptargfaction = phisFactionArray[j];
                                ireturnReaction = ireaction_2;
                            }
                        }
                    }
                }
            }
        }
    }
    return ireturnReaction;
}

