                        int32_t iMonthBits = static_cast<int32_t>(appCalendar.GetMonth()) << 9;
                        int32_t v10 = appCalendar.GetDay() | iMonthBits;
                        iThiefCrimeStamp = appCalendar.GetYear() << 13 | v10;
